  background:
    radial-gradient(circle at 88% 10%, rgba(255,193,7,0.28), transparent 30%),
    radial-gradient(circle at 10% 90%, rgba(255,152,0,0.18), transparent 35%),
    linear-gradient(135deg, rgba(15,23,42,0.98), rgba(30,41,59,0.97));
  border: 1px solid rgba(148,163,184,0.20);
  border-radius: 28px;
  box-shadow: 0 18px 45px rgba(0,0,0,0.30);
  padding: 22px 26px;
}

{% set el = state_attr('sun.sun', 'elevation') | float(0) %}
ha-card {
  border-radius: 28px;
  overflow: hidden;
  min-height: 360px;
  {% if el > 15 %}
  background: linear-gradient(180deg, rgba(21,135,232,0.92) 0%, rgba(99,186,245,0.86) 48%, rgba(188,231,255,0.82) 100%) !important;
  {% elif el > 0 %}
  background: linear-gradient(180deg, rgba(38,118,186,0.94) 0%, rgba(117,183,223,0.90) 46%, rgba(255,192,128,0.86) 78%, rgba(255,155,95,0.88) 100%) !important;
  {% elif el > -6 %}
  background: linear-gradient(180deg, rgba(23,27,60,0.98) 0%, rgba(81,67,112,0.95) 42%, rgba(199,101,103,0.90) 70%, rgba(255,152,102,0.90) 100%) !important;
  {% else %}
  background:
    radial-gradient(circle at 12% 15%, rgba(255,255,255,0.8) 0px, transparent 1.5px),
    radial-gradient(circle at 35% 13%, rgba(255,255,255,0.75) 0px, transparent 1.4px),
    radial-gradient(circle at 55% 20%, rgba(255,255,255,0.7) 0px, transparent 1.5px),
    radial-gradient(circle at 76% 12%, rgba(255,255,255,0.8) 0px, transparent 1.3px),
    radial-gradient(circle at 94% 45%, rgba(255,255,255,0.7) 0px, transparent 1.4px),
    linear-gradient(180deg, #020817 0%, #071329 48%, #10264b 75%, #24436b 100%) !important;
  animation: starsTwinkle 5s ease-in-out infinite alternate;
  {% endif %}
  box-shadow: 0 16px 38px rgba(0,0,0,0.30);
}
@keyframes starsTwinkle {
  from { filter: brightness(0.90); }
  to   { filter: brightness(1.12); }
}

cards.content:
{% set az = state_attr('sun.sun','azimuth') | float(0) %}
{% set el = state_attr('sun.sun','elevation') | float(0) %}
{% set nr = state_attr('sun.sun','next_rising') %}
{% set ns = state_attr('sun.sun','next_setting') %}

## ☀️ Solar position

**Status:** {% if el > 6 %}Day{% elif el > 0 %}Golden hour{% elif el > -6 %}Twilight{% else %}Night{% endif %}

**Elevation:** {{ el | round(1) }}°  
**Azimuth:** {{ az | round(1) }}°  
**Direction:** {% if az >= 337.5 or az < 22.5 %}North{% elif az < 67.5 %}North-East{% elif az < 112.5 %}East{% elif az < 157.5 %}South-East{% elif az < 202.5 %}South{% elif az < 247.5 %}South-West{% elif az < 292.5 %}West{% else %}North-West{% endif %}

---

**Next sunrise:** {{ as_timestamp(nr) | timestamp_custom('%-I:%M %p') if nr else '—' }}  
**Next sunset:** {{ as_timestamp(ns) | timestamp_custom('%-I:%M %p') if ns else '—' }}

{% if is_state('sun.sun','above_horizon') %}
🌞 **Sun is above the horizon**
{% else %}
🌙 **Sun is {{ el | abs | round(1) }}° below the horizon**
{% endif %}

